#include "ir.hpp"
#include <sstream>
namespace g2m {
IRModule lowerToIR(const Program& p){IRModule m;m.name=p.moduleName;for(const auto&f:p.functions){if(f.declarationOnly)continue;IRFunction out{f.name,{}};int next=0;for(const auto&s:f.body){switch(s.kind){case Statement::Kind::VariableI32:out.instructions.push_back({"const.i32","%v"+std::to_string(next++),s.value});out.instructions.push_back({"local.set",s.name,out.instructions.back().result});break;case Statement::Kind::PrintString:out.instructions.push_back({"call","","printn "+(s.arguments.empty()?std::string{}:s.arguments[0].value)});break;case Statement::Kind::Printf:{std::ostringstream args;for(std::size_t i=0;i<s.arguments.size();++i){if(i)args<<", ";args<<s.arguments[i].type<<" "<<s.arguments[i].value;}out.instructions.push_back({"call.variadic","","printfn("+args.str()+")"});break;}case Statement::Kind::PrintIdentifier:case Statement::Kind::Call:{std::ostringstream args;for(std::size_t i=0;i<s.arguments.size();++i){if(i)args<<", ";args<<s.arguments[i].value;}out.instructions.push_back({"call","",s.name+"("+args.str()+")"});break;}}}out.instructions.push_back({"return","","nil"});m.functions.push_back(std::move(out));}return m;}
std::string printIR(const IRModule&m){std::ostringstream o;o<<"module @"<<m.name<<" {\n";for(const auto&f:m.functions){o<<"function @"<<f.name<<" {\n";for(const auto&i:f.instructions){o<<"  ";if(!i.result.empty())o<<i.result<<" = ";o<<i.opcode;if(!i.operand.empty())o<<" "<<i.operand;o<<"\n";}o<<"}\n";}o<<"}\n";return o.str();}
}
